import fs from "node:fs/promises";
import path from "node:path";

const OUTPUT_PATH = path.resolve(
  "client/src/data/openRouterMarketSnapshot.ts",
);
const MODELS_PATH = path.resolve("client/src/data/models.ts");
const MARKET_URL =
  "https://openrouter.ai/api/frontend/v1/models/find?active=true&fmt=cards";
const LEGACY_RANKING_MARKER =
  "const openRouterUseCaseRankingsByModelId: Record<string, OpenRouterCategoryRanking[]> = ";
const LEGACY_RANKING_END_MARKER =
  "// Generated by scripts/update-openrouter-models.mjs. Entries remain callable";

const SERIES = new Set([
  "GPT",
  "Claude",
  "Gemini",
  "Gemma",
  "Grok",
  "Cohere",
  "Nova",
  "Qwen",
  "Yi",
  "DeepSeek",
  "Mistral",
  "Llama2",
  "Llama3",
  "Llama4",
  "RWKV",
  "Qwen3",
  "Router",
  "Media",
  "Other",
  "PaLM",
]);
const CATEGORY_ORDER = [
  "programming",
  "roleplay",
  "marketing",
  "marketing/seo",
  "technology",
  "science",
  "translation",
  "legal",
  "finance",
  "health",
  "trivia",
  "academia",
];
const CATEGORY_SET = new Set(CATEGORY_ORDER);
const REGION_ORDER = ["eu", "us"];
const DESIGN_ARENA_KEYS = {
  "models-codecategories": "code_categories",
  "models-uicomponent": "ui_component",
  "models-gamedev": "game_development",
  "models-dataviz": "data_visualization",
  "models-3d": "3d",
  "models-image": "image",
  "models-video": "video",
  "models-svg": "svg",
};

function readArgument(name) {
  const index = process.argv.indexOf(name);
  return index >= 0 ? process.argv[index + 1] : "";
}

function stripBatchSuffix(value) {
  return String(value ?? "").replace(/:batch$/, "");
}

function createSnapshot() {
  return {
    series: "Other",
    author: "",
    providers: new Set(),
    categories: new Set(),
    discounted: false,
    distillable: false,
    zero_data_retention: false,
    regions: new Set(),
    created_at: null,
    tool_call_success_rate: null,
    artificial_analysis: {},
    design_arena: {},
  };
}

async function loadPayload() {
  const inputPath = readArgument("--input");
  if (inputPath) {
    return JSON.parse(await fs.readFile(path.resolve(inputPath), "utf8"));
  }
  const response = await fetch(MARKET_URL, {
    headers: {
      Accept: "application/json",
      Referer: "https://openrouter.ai/models",
      "User-Agent": "Mozilla/5.0",
    },
  });
  if (!response.ok) {
    throw new Error(`OpenRouter model market request failed: HTTP ${response.status}`);
  }
  return response.json();
}

function removeLegacyRankingBlock(source) {
  const start = source.indexOf(LEGACY_RANKING_MARKER);
  if (start < 0) return source;
  const end = source.indexOf(LEGACY_RANKING_END_MARKER, start);
  if (end < 0) {
    throw new Error("Legacy category ranking block has no closing marker");
  }
  return source.slice(0, start) + source.slice(end);
}

function resolveRegion(providerRegion) {
  const normalized = String(providerRegion ?? "").toLowerCase();
  if (normalized.startsWith("eu")) return "eu";
  if (normalized.startsWith("us")) return "us";
  return null;
}

function roundMetric(value) {
  return Number(Number(value).toFixed(2));
}

function serializeSnapshot(snapshot) {
  return {
    series: snapshot.series,
    author: snapshot.author,
    providers: [...snapshot.providers].sort((left, right) =>
      left.localeCompare(right),
    ),
    categories: CATEGORY_ORDER.filter((category) =>
      snapshot.categories.has(category),
    ),
    discounted: snapshot.discounted,
    distillable: snapshot.distillable,
    zero_data_retention: snapshot.zero_data_retention,
    regions: REGION_ORDER.filter((region) => snapshot.regions.has(region)),
    created_at: snapshot.created_at,
    tool_call_success_rate: snapshot.tool_call_success_rate,
    artificial_analysis: snapshot.artificial_analysis,
    design_arena: snapshot.design_arena,
  };
}

async function main() {
  const payload = await loadPayload();
  const data = payload?.data;
  if (!Array.isArray(data?.models)) {
    throw new Error("OpenRouter model market response is missing data.models[]");
  }

  const snapshots = new Map();
  const aliases = new Map();

  for (const record of data.models) {
    const variantId =
      record?.endpoint?.model_variant_slug || record?.slug || "";
    const modelId = stripBatchSuffix(variantId);
    if (!modelId) continue;
    const snapshot = snapshots.get(modelId) ?? createSnapshot();
    snapshots.set(modelId, snapshot);

    if (SERIES.has(record.group)) snapshot.series = record.group;
    if (record.author) snapshot.author = String(record.author);
    if (record.endpoint?.provider_name) {
      snapshot.providers.add(String(record.endpoint.provider_name));
    }
    snapshot.discounted ||= Number(record.endpoint?.pricing?.discount ?? 0) > 0;
    snapshot.distillable ||=
      record.is_trainable_text === true || record.is_trainable_image === true;
    snapshot.zero_data_retention ||=
      record.endpoint?.data_policy?.retainsPrompts === false;
    const region = resolveRegion(record.endpoint?.provider_region);
    if (region) snapshot.regions.add(region);

    const createdAt = Date.parse(record.created_at ?? "");
    if (Number.isFinite(createdAt)) {
      const createdSeconds = Math.floor(createdAt / 1000);
      snapshot.created_at =
        snapshot.created_at === null
          ? createdSeconds
          : Math.min(snapshot.created_at, createdSeconds);
    }

    for (const alias of [
      record.slug,
      record.permaslug,
      record.endpoint?.model_variant_slug,
      record.endpoint?.model_variant_permaslug,
      record.endpoint?.model?.slug,
      record.endpoint?.model?.permaslug,
    ]) {
      if (alias) aliases.set(stripBatchSuffix(alias), modelId);
    }
  }

  const resolveModelId = (value) => {
    const normalized = stripBatchSuffix(value);
    return aliases.get(normalized) ?? normalized;
  };

  for (const [sourceId, placements] of Object.entries(data.categories ?? {})) {
    const snapshot = snapshots.get(resolveModelId(sourceId));
    if (!snapshot || !Array.isArray(placements)) continue;
    for (const placement of placements) {
      if (CATEGORY_SET.has(placement?.category)) {
        snapshot.categories.add(placement.category);
      }
    }
  }

  for (const [sourceId, analytics] of Object.entries(data.analytics ?? {})) {
    const snapshot = snapshots.get(resolveModelId(sourceId));
    if (!snapshot) continue;
    const toolCallCount = Number(analytics?.total_tool_calls ?? 0);
    const toolCallErrors = Number(
      analytics?.requests_with_tool_call_errors ?? 0,
    );
    if (toolCallCount > 0 && toolCallErrors >= 0) {
      snapshot.tool_call_success_rate = roundMetric(
        Math.max(
          0,
          Math.min(100, ((toolCallCount - toolCallErrors) / toolCallCount) * 100),
        ),
      );
    }
  }

  for (const [sourceId, benchmark] of Object.entries(data.benchmarks ?? {})) {
    const snapshot = snapshots.get(resolveModelId(sourceId));
    if (!snapshot) continue;
    for (const metric of [
      "intelligence_index",
      "coding_index",
      "agentic_index",
    ]) {
      const value = Number(benchmark?.aa?.[metric]);
      if (Number.isFinite(value)) {
        snapshot.artificial_analysis[metric] = roundMetric(value);
      }
    }
    for (const [sourceMetric, targetMetric] of Object.entries(
      DESIGN_ARENA_KEYS,
    )) {
      const value = Number(benchmark?.da?.elo_by_category?.[sourceMetric]);
      if (Number.isFinite(value)) {
        snapshot.design_arena[targetMetric] = roundMetric(value);
      }
    }
  }

  const output = Object.fromEntries(
    [...snapshots.entries()]
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([modelId, snapshot]) => [modelId, serializeSnapshot(snapshot)]),
  );
  const generatedAt = new Date().toISOString();
  const source = `import type { OpenRouterMarketSnapshot } from "./openRouterMarket";\n\n// Generated by scripts/update-openrouter-market-filters.mjs.\nexport const openRouterMarketSnapshotGeneratedAt = ${JSON.stringify(generatedAt)};\nexport const openRouterMarketSnapshotSource = ${JSON.stringify(MARKET_URL)};\nexport const openRouterMarketSnapshotByModelId: Record<string, OpenRouterMarketSnapshot> = ${JSON.stringify(output, null, 2)};\n`;

  await fs.writeFile(OUTPUT_PATH, source, "utf8");
  const modelSource = await fs.readFile(MODELS_PATH, "utf8");
  const cleanedModelSource = removeLegacyRankingBlock(modelSource);
  if (cleanedModelSource !== modelSource) {
    await fs.writeFile(MODELS_PATH, cleanedModelSource, "utf8");
  }

  console.log(
    JSON.stringify(
      {
        source: MARKET_URL,
        generated_at: generatedAt,
        source_records: data.models.length,
        model_snapshots: Object.keys(output).length,
        category_models: Object.values(output).filter(
          (item) => item.categories.length > 0,
        ).length,
        discounted_models: Object.values(output).filter(
          (item) => item.discounted,
        ).length,
      },
      null,
      2,
    ),
  );
}

await main();
